require("dotenv").config();const Database=require("better-sqlite3");const db=new Database("./data/jobs.sqlite");db.exec("CREATE TABLE IF NOT EXISTS admin_users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL)");const u=process.env.ADMIN_USERNAME,h=process.env.ADMIN_PASSWORD_HASH;if(!u||!h){throw new Error("Set ADMIN_USERNAME and ADMIN_PASSWORD_HASH in .env")}db.prepare("INSERT INTO admin_users(username,password_hash) VALUES(?,?) ON CONFLICT(username) DO UPDATE SET password_hash=excluded.password_hash").run(u,h);console.log("Admin user bootstrapped:",u);